import java.io.*;

public class Main {
    static long[] bloom;
    static long k, need;

    // Can we make `need` bouquets of k adjacent roses by `day`?
    static boolean possible(long day) {
        long bouquets = 0, run = 0;
        for (long b : bloom) {
            if (b <= day) {
                if (++run == k) { run = 0; if (++bouquets >= need) return true; }
            } else run = 0;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int size = (int) st.nval;
        st.nextToken();
        k = (long) st.nval;
        st.nextToken();
        need = (long) st.nval;
        bloom = new long[size];
        long low = Long.MAX_VALUE, high = Long.MIN_VALUE;
        for (int i = 0; i < size; i++) {
            st.nextToken();
            bloom[i] = (long) st.nval;
            low = Math.min(low, bloom[i]);
            high = Math.max(high, bloom[i]);
        }
        if (k * need > size) { System.out.println(-1); return; }
        while (low < high) {
            long mid = (low + high) / 2;
            if (possible(mid)) high = mid;
            else low = mid + 1;
        }
        System.out.println(low);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	size, k, need := nextInt(), nextInt(), nextInt()
	bloom := make([]int, size)
	for i := range bloom {
		bloom[i] = nextInt()
	}
	if k*need > size {
		fmt.Println(-1)
		return
	}
	// Can we make `need` bouquets of k adjacent roses by `day`?
	possible := func(day int) bool {
		bouquets, run := 0, 0
		for _, b := range bloom {
			if b <= day {
				run++
				if run == k {
					run = 0
					bouquets++
					if bouquets >= need {
						return true
					}
				}
			} else {
				run = 0
			}
		}
		return false
	}
	low, high := slices.Min(bloom), slices.Max(bloom)
	for low < high {
		mid := (low + high) / 2
		if possible(mid) {
			high = mid
		} else {
			low = mid + 1
		}
	}
	fmt.Println(low)
}
